WITH cleaned AS (SELECT id, product_id, quantity, last_restock, CASE WHEN quantity >= 201 THEN 'High' WHEN quantity >= 104 THEN 'Medium' ELSE 'Low' END AS quantity_band, DATEDIFF(CURRENT_DATE(), last_restock) / 30 AS months_since_last_restock FROM inventory WHERE store_id = 6) SELECT product_id, id FROM cleaned INTERSECT ALL SELECT product_id, id FROM inventory WHERE product_id IN (5, 6, 8)
